<template>
  <div>
    <div class="container" v-if="user_permissions.includes('is_programmer')">
        <Mjuni/> 
    </div>
    <div class="d-flex mb-2">
     <h5 class="me-auto">{{ title }}</h5>
      <button
        v-if="user_permissions.includes('can_register_'+ props.form)"
      @click="toggleNew" class="me-1 btn" :class="!newEntity ? 'btn-primary' : 'btn-danger'">
        {{ !newEntity ? '+ NEW' : 'X' }}
      </button>
      <button @click="printData()" class="btn btn-success fs-4 px-3">
        <i class="bi bi-printer"></i>
      </button>
    </div>

    <form v-if="newEntity" @submit.prevent="submit">
      <div class="row mb-3">
      <div v-for="field in fields" :key="field.id" :class="field.field_type === 'textarea' ? 'col-md-12' : 'col-md-4'">
        <label class="form-label small text-muted">{{ field.field_label }}</label>

        <input v-if="field.field_type === 'text' || field.field_type === 'email'"
               v-model="formData[field.field_name]"
               :type="field.field_type"
               class="form-control form-control-sm"
               :required="field.is_required"
               :placeholder="field.field_label" />

        <input v-else-if="field.field_type === 'number'"
               type="number"
               v-model="formData[field.field_name]"
               class="form-control form-control-sm"
               :placeholder="field.field_label" />

        <input v-else-if="field.field_type === 'date'"
               type="date"
               v-model="formData[field.field_name]"
               class="form-control form-control-sm" />

<div v-else-if="field.field_type === 'checkbox'" class="form-check mt-1">
  <input
    type="checkbox"
    class="form-check-input"
    :id="`chk_${field.field_name}`"
    v-model="formData[field.field_name]" />
  <label class="form-check-label small" :for="`chk_${field.field_name}`">
    {{ formData[field.field_name] ? 'Yes' : 'No' }}
  </label>
</div>

               <input v-else-if="field.field_type === 'file'"
       type="file"
       class="form-control form-control-sm"
       :accept="field.accepted_types || undefined"
       :required="field.is_required"
       @change="handleFile(field.field_name, $event)" />

        <textarea v-else-if="field.field_type === 'textarea'"
                  v-model="formData[field.field_name]"
                  class="form-control form-control-sm"
                  rows="3"
                  :placeholder="field.field_label"></textarea>

        <select v-else-if="field.field_type === 'select'"
                v-model="formData[field.field_name]"
                class="form-select form-select-sm">
          <option value="">Select...</option>
          <option v-for="o in field.options" :key="o" :value="o">{{ o }}</option>
        </select>

<Multiselect
  v-else-if="field.field_type === 'relation'"
  v-model="formData[field.field_name]"
  :options="relatedData[field.field_name]"
  :searchable="true"
  :close-on-select="true"
  :clear-on-select="false"
  :preserve-search="true"
  :custom-label="(option) => getRelatedOptionLabel(option, field)"
  track-by="id"
  label="id"
  placeholder="Search & select"
/>

      </div>
      </div>


      <div class="d-flex gap-2 ">
        <div class="ms-auto">
        <button class="btn btn-sm btn-dark me-2" :disabled="saving">
          <span v-if="saving" class="spinner-border spinner-border-sm "></span>
          {{ saving ? 'Saving...' : editingId ? 'Update' : 'Save' }}
        </button>
        <button v-if="editingId" type="button" class="btn btn-sm btn-outline-secondary" @click="cancelEdit">
          Cancel
        </button>
        </div>
      </div>
    </form>

    <hr />

    <table v-if="rows.length" class="table table-sm table-bordered table-hover table-striped">
      <thead class="table-light">
        <tr>
          <th class="small text-muted fw-semibold">Sno</th>
          <th v-for="f in fields" :key="f.id" class="small text-muted fw-semibold">
            {{ f.field_label }}
          </th>
          <th class="small text-muted fw-semibold" style="width: 90px;">Actions</th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="(row ,index ) in rows" :key="row.id">
          <td>{{ index + 1 }}</td>
<td v-for="f in fields" :key="f.id" class="small align-middle ">
  <template v-if="f.field_type === 'file'">
    <a v-if="row[f.field_name]" 
       :href="`https://bushman.ink/${row[f.field_name]}`" 
       target="_blank" 
       class="small badge-primary badge text-white">
      Open Link 
    </a>
    <span v-else class="text-muted">—</span>
  </template>
<template v-else-if="f.field_type === 'relation'">
  <template v-if="row[f.field_name]">
    <div>{{ getRelatedDisplay(row, f) }}</div>
    <sub v-if="f.nested_display" class="text-muted" style="font-size:10px;">
      {{ getNestedLabel(row, f) }}
    </sub>
  </template>
  <span v-else class="text-muted">—</span>
</template>
  <template v-else-if="f.field_type === 'checkbox'">
  {{ row[f.field_name] ? 'Yes' : 'No' }}
</template>
  <template v-else>
    {{ row[f.field_name] }}
  </template>
</td>
          <td class="small align-middle">
            <div class="d-flex gap-1">
              <button
              v-if="user_permissions.includes('can_edit_'+ props.form)"
              class="btn btn-xs btn-outline-primary" style="font-size:11px;padding:1px 7px;" @click="editRow(row)">
                Edit 
              </button>
              <button
               v-if="user_permissions.includes('can_delete_'+ props.form)"
                class="btn btn-xs btn-outline-danger"
                style="font-size:11px;padding:1px 7px;"
                :disabled="deletingId === row.id"
                @click="deleteRow(row.id)"
              >
                {{ deletingId === row.id ? '...' : 'Delete' }}
              </button>
            </div>
          </td>
        </tr>
      </tbody>
    </table>

    <div v-else-if="loading" class="text-center text-muted py-4">
      <span class="spinner-border spinner-border-sm me-1"></span> Loading...
    </div>

    <div v-else class="text-center text-muted py-4 border rounded" style="border-style:dashed!important;">
      No records found
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, inject } from 'vue'
import axios from 'axios'
import Multiselect from '@suadelabs/vue3-multiselect';
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';

const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
const showMessage = inject('showMessage')
const showError   = inject('showError')

const props = defineProps({ form: { type: String, required: true } })

const title = ref('')

const fields      = ref([])
const formData    = ref({})
const relatedData = ref({})
const rows        = ref([])
const newEntity   = ref(false)
const loading     = ref(true)
const saving      = ref(false)
const editingId   = ref(null)
const deletingId  = ref(null)

const api = axios.create({ baseURL: 'https://bushman.ink/api/v2/' })


const handleFile = (fieldName, event) => {
  formData.value[fieldName] = event.target.files[0] ?? null
}




const loadFields = async () => {
  try {
    const res = await api.get('forms')
    const formObj = res.data.find(f => f.name === props.form)
    fields.value = formObj?.fields ?? []
    title.value  = formObj?.title ?? props.form

    for (const f of fields.value) {
      if (f.field_type === 'relation' && f.related_form?.name) {
        const related = await api.get(`modules/${f.related_form.name}`)
        relatedData.value[f.field_name] = related.data
      }
      if (f.field_type === 'file') {
        formData.value[f.field_name] = null
      } else if (f.field_type === 'checkbox') {
        formData.value[f.field_name] = f.default_checked ?? false
      } else {
        formData.value[f.field_name] = ''
      }
    }
  } catch(error) {
    console.log(error.message)
    showError(error.message)
  }
}



const loadRows = async () => {
  loading.value = true
  try {
    const res = await api.get(`modules/${props.form}`)
    rows.value = res.data
  } finally {
    loading.value = false
  }
}

const getRelatedDisplay = (row, field) => {
  const val = row[field.field_name]
  if (!val) return '—'
  if (typeof val !== 'object') return val

  // Always show parent using display_column — ignore nested_display here
  const col = field.display_column || 'name'
  return val[col] || val.name || val.title || val.label || `#${val.id}`
}

const getNestedLabel = (row, field) => {
  if (!field.nested_display) return ''
  const keys = field.nested_display.split('.')
  const val  = row[field.field_name]
  if (!val || typeof val !== 'object') return '—'

  let result = val
  for (const key of keys) {
    result = result?.[key]
    if (result === undefined || result === null) return '—'
  }
  return result
}

const clearForm = () => {
  for (const f of fields.value) {
    if (f.field_type === 'file') {
      formData.value[f.field_name] = null
    } else if (f.field_type === 'checkbox') {
      formData.value[f.field_name] = f.default_checked ?? false
    } else {
      formData.value[f.field_name] = ''
    }
  }
  editingId.value = null
}

const toggleNew = () => {
  newEntity.value = !newEntity.value
  if (!newEntity.value) cancelEdit()
}

const cancelEdit = () => {
  clearForm()
  newEntity.value = false
}

// Populate form with row data for editing
const editRow = (row) => {
  editingId.value = row.id
  for (const f of fields.value) {
    const val = row[f.field_name]
    // For relation fields, extract the id if it's an object
   formData.value[f.field_name] =
  (f.field_type === 'relation' && typeof val === 'object')
    ? val
    : val ?? null
  }
  newEntity.value = true
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

const submit = async () => {
  saving.value = true
  try {
    const hasFile = fields.value.some(f => f.field_type === 'file')

    let payload

    if (hasFile) {
      payload = new FormData()

      for (const [key, val] of Object.entries(formData.value)) {
        if (val && typeof val === 'object' && val.id) {
          payload.append(key, val.id)
        } else {
          payload.append(key, val)
        }
      }

      if (editingId.value) payload.append('_method', 'PUT')

    } else {
      payload = {}

      for (const [key, val] of Object.entries(formData.value)) {
        payload[key] = (val && typeof val === 'object' && val.id)
          ? val.id
          : val
      }
    }

    const config = hasFile ? { headers: { 'Content-Type': 'multipart/form-data' } } : {}

    if (editingId.value && !hasFile) {
      await api.put(`modules/${props.form}/${editingId.value}`, payload, config)
    } else if (editingId.value && hasFile) {
      await api.post(`modules/${props.form}/${editingId.value}`, payload, config)
    } else {
      await api.post(`modules/${props.form}`, payload, config)
    }

    showMessage?.('Saved successfully.')
    cancelEdit()
    await loadRows()

  } catch(error) {
    showError?.('Failed to save.')
    console.log(error)
  } finally {
    saving.value = false
  }
}

const getRelatedOptionLabel = (r, field) => {
  const parent = r[field.display_column] || r.name || r.title || r.label || `#${r.id}`

  if (!field.nested_display) return parent

  const keys = field.nested_display.split('.')
  let nested = r
  for (const key of keys) {
    nested = nested?.[key]
    if (nested === undefined || nested === null) return parent
  }

  return `${parent} - ${nested}`
}


const deleteRow = async (id) => {
  if (!confirm('Delete this record? This cannot be undone.')) return

  deletingId.value = id
  try {
    await api.delete(`modules/${props.form}/${id}`)
    showMessage?.('Record deleted.')
    await loadRows()
  } catch (err) {
    showError?.(err.response?.data?.message ?? 'Failed to delete record.')
  } finally {
    deletingId.value = null
  }
}

const printData = () =>{
   try {
    const iframe = document.createElement("iframe");
    iframe.style.display = "none";
    document.body.appendChild(iframe);

    const printContent = `
<!DOCTYPE html>
<html>
<head>
<title> ${title.value.toUpperCase()} List</title>
<style>
  body { font-family: 'Courier New', monospace; margin: 40px; font-size: 11px; }
  .text-style { font-family: 'Courier New', monospace; }
  .company-title { text-align: center; }
  .title { text-align: center; font-size: 18px; margin: 10px 0; }
  table { width: 95%; border-collapse: collapse; margin: 10px auto; font-size: 11px; }
  th, td { border: 0.5px solid #000; padding: 4px; }
  th { background-color: #f8f8f8; font-weight: bold; }
  .text-right { text-align: right; }
  .text-center { text-align: center; }
  hr { border: 0; border-top: 0.5px solid #000; margin: 0px 0; }
  @media print { body { margin: 10mm; } }
</style>
</head>
<body>

<div class="company-title text-style">
  <i>
  <h1>COPEX CONTRACTORS CO.LTD</h1>
  <div><b>Address:</b> Msamvu, P.O.BOX 678, Morogoro</div>
  <div><b>Tel:</b> 0713 000 777, 0657 111 555</div>
  <div><b>Email:</b> info@copexcontractors.co.tz</div>
  <div><b>TIN:</b> 135-489-247 &nbsp;&nbsp; <b>VRN:</b> 40-032826C</div>
  </i>
</div>

<hr style="margin-top:20px">

<div class="title text-style">
  ${title.value.toUpperCase()} LIST
</div>

<hr>

<table>
  <thead>
    <tr>
          <th>Sno</th>
       ${fields.value.map((f, index) => `
          <th>${f.field_label}</th>
    `).join('')}
    </tr>
  </thead>
  <tbody>
    ${rows.value.map((row, index) => `
<tr>
  <td>${index + 1}</td>

  ${fields.value.map(f => {
    if (f.field_type === 'file') {
      return `
        <td class="small align-middle">
          ${
            row[f.field_name]
              ? `<a href="https://bushman.ink/${row[f.field_name]}" target="_blank" class="small badge-primary badge text-white">Open Link</a>`
              : `<span class="text-muted">—</span>`
          }
        </td>
      `;
    }

    if (f.field_type === 'relation') {
      return `
        <td class="small align-middle">
          ${
            row[f.field_name]
              ? `
                <div>${getRelatedDisplay(row, f)}</div>
                ${
                  f.nested_display
                    ? `<sub class="text-muted" style="font-size:10px;">${getNestedLabel(row, f)}</sub>`
                    : ``
                }
              `
              : `<span class="text-muted">—</span>`
          }
        </td>
      `;
    }

    if (f.field_type === 'checkbox') {
      return `
        <td class="small align-middle">
          ${row[f.field_name] ? 'Yes' : 'No'}
        </td>
      `;
    }

    return `
      <td class="small align-middle">
        ${row[f.field_name] ?? ''}
      </td>
    `;
  }).join('')}

</tr>
`).join('')}
  </tbody>
</table>

</body>
</html>
`;

    const iframeDoc = iframe.contentWindow.document;
    iframeDoc.open();
    iframeDoc.write(printContent);
    iframeDoc.close();

    iframe.onload = () => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
      setTimeout(() => {
        document.body.removeChild(iframe);
      }, 1000);
    };
  } catch (error) {
    showError(`Failed to print report: ${error.message}`);
  }
}

onMounted(async () => {
  await loadFields()
  await loadRows()
})
</script>